{
  "lines": [
    {
      "id": "progress.first_pr",
      "tiers": [
        {
          "id": "progress.first_pr:t1",
          "title": "Прогресс высунул рожки",
          "phrase": "Первый день с подтверждённым улучшением относительно прошлой сопоставимой сессии — у тебя в копилке. Прогресс высунул рожки!",
          "imagePrompt": "A curious snail pulls a small folding staircase from its shell and checks the first raised step with oversized calipers. Its eyestalks lean toward the gap between the new step and a lower comparison block.",
          "fishMarkup": "[warm] Первый день с подтверждённым улучшением относительно прошлой сопоставимой сессии — у тебя в копилке. [playful] Прогресс высунул рожки!",
          "audioText": "Первый день с подтверждённым улучшением относительно прошлой сопоставимой сессии — у тебя в копилке. Прогресс высунул рожки!"
        },
        {
          "id": "progress.first_pr:t2",
          "title": "Лестница раскладывается",
          "phrase": "У тебя уже 2 дня с подтверждёнными улучшениями относительно прошлых сопоставимых сессий. Это не эхо: лестница правда подросла.",
          "imagePrompt": "The snail turns a crank on its shell, extending the folding staircase into a taller zigzag. Oversized calipers hang from the crank handle, while the lowest stair remains tucked inside the open shell.",
          "fishMarkup": "[confident] У тебя уже <emphasis>2 дня</emphasis> с подтверждёнными улучшениями относительно прошлых сопоставимых сессий. [playful] Это не эхо: лестница правда подросла.",
          "audioText": "У тебя уже 2 дня с подтверждёнными улучшениями относительно прошлых сопоставимых сессий. Это не эхо: лестница правда подросла."
        },
        {
          "id": "progress.first_pr:t3",
          "title": "Лифт для лестницы",
          "phrase": "Ты накопил 5 дней с подтверждёнными улучшениями относительно прошлых сопоставимых сессий. Лестница прогресса заказала себе лифт!",
          "imagePrompt": "The snail operates a crank-powered freight lift beside its unfolded shell staircase. A folded section of stairs rides inside, lounging in a tiny armchair with its lowest step resting on a footstool.",
          "fishMarkup": "[triumphant] Ты накопил <emphasis>5 дней</emphasis> с подтверждёнными улучшениями относительно прошлых сопоставимых сессий. Лестница прогресса <slow>заказала себе лифт!</slow>",
          "audioText": "Ты накопил 5 дней с подтверждёнными улучшениями относительно прошлых сопоставимых сессий. Лестница прогресса заказала себе лифт!"
        }
      ]
    },
    {
      "id": "progress.rep_pr",
      "tiers": [
        {
          "id": "progress.rep_pr:t1",
          "title": "Первый щелчок счётов",
          "phrase": "Первый день рекорда повторений: ты сделал больше повторов, чем в прошлой сопоставимой сессии, при том же весе. Железо даже не переодевалось!",
          "imagePrompt": "A small octopus slides a bead across a wooden abacus with the tip of a curled tentacle. A dumbbell rests horizontally on a squat stand beside it, while another tentacle steadies the abacus frame.",
          "fishMarkup": "[warm] Первый день рекорда повторений: ты сделал больше повторов, чем в прошлой сопоставимой сессии, при том же весе. [playful] Железо даже не переодевалось!",
          "audioText": "Первый день рекорда повторений: ты сделал больше повторов, чем в прошлой сопоставимой сессии, при том же весе. Железо даже не переодевалось!"
        },
        {
          "id": "progress.rep_pr:t2",
          "title": "Счёт с характером",
          "phrase": "На твоём счету 3 дня рекорда повторений при том же весе и сопоставимых условиях. Счёты раскрыли дополнительные секции — вот это поворот!",
          "imagePrompt": "The octopus unfolds hinged wings from its wooden abacus, revealing extra bead rails like a concertina. Several tentacles slide beads in different sections; the familiar dumbbell remains on its squat stand.",
          "fishMarkup": "[confident] На твоём счету <emphasis>3 дня</emphasis> рекорда повторений при том же весе и сопоставимых условиях. [playful] Счёты раскрыли дополнительные секции — вот это поворот!",
          "audioText": "На твоём счету 3 дня рекорда повторений при том же весе и сопоставимых условиях. Счёты раскрыли дополнительные секции — вот это поворот!"
        },
        {
          "id": "progress.rep_pr:t3",
          "title": "Туш на счётах",
          "phrase": "Ты собрал 8 дней рекорда повторений при том же весе и сопоставимых условиях. Счёты теперь играют туш!",
          "imagePrompt": "The octopus performs with its fully expanded abacus held like an enormous accordion, tentacles sweeping the bead rails. The familiar dumbbell sits upright on its squat stand, listening through a tiny ear trumpet.",
          "fishMarkup": "[triumphant] Ты собрал <emphasis>8 дней</emphasis> рекорда повторений при том же весе и сопоставимых условиях. Счёты теперь <slow>играют туш!</slow>",
          "audioText": "Ты собрал 8 дней рекорда повторений при том же весе и сопоставимых условиях. Счёты теперь играют туш!"
        }
      ]
    }
  ]
}
